#include <unordered_set>


class FindElements {
    unordered_set<int> vals;

public:
    FindElements(TreeNode* root) {
        dfs(root, 0);
    }

    void dfs(TreeNode* node, int val) {
        if (!node) return;
        node->val = val;
        vals.insert(val);
        dfs(node->left, 2 * val + 1);
        dfs(node->right, 2 * val + 2);
    }

    bool find(int target) {
        return vals.count(target);
    }
};
